  str_world_boss_element = "Elemento jefe",
  str_world_boss_result_select = "Seleccionar",
  str_world_boss_bossdesc_7101005 = "Daño del contador de elementos aurorianos +100 %.\nAcumula el efecto de Asalto al golpear monstruos. Las acumulaciones se restablecerán a cero después de recibir daño.",
  str_world_boss_leveldesc_normal_7101005 = "- Los Aurorianos pueden acumular el efecto de Asalto al golpear monstruos. Después de ser atacado por monstruos y <color=#cc0e0e>perdiendo HP, el número de acumulaciones se restablecerá a cero</color>.\n- El efecto de Asalto se acumula hasta <color=#cc0e0e>100</color> veces.",
  str_world_boss_leveldesc_hard_7101005 = "- Los Aurorianos pueden acumular el efecto de Asalto al golpear monstruos. Después de ser atacado por monstruos y <color=#cc0e0e>perder HP, el número de acumulaciones se restablecerá a cero</color>.\n- El efecto de Asalto se acumula hasta <color=#cc0e0e>150</color> veces.\n- Astor inflige una pequeña cantidad de daño a los Aurorianos cada vez que se enciende una Vela de la Muerte.",
  str_world_boss_bossdesc_7101001 = "Daño del contador de elementos aurorianos +100 %.\nLos aurorianos ganan 1 ficha mejorada por cada 3 fichas que mueven.",
  str_world_boss_leveldesc_normal_7101001 = "- Los aurorianos ganan 1 ficha mejorada por cada 3 fichas que mueven.",
  str_world_boss_leveldesc_hard_7101001 = "- Los aurorianos ganan 1 ficha mejorada por cada 3 fichas que mueven.\n- Incrementos <color=#cc0e0e>Daño combinado en cadena</color> tomado por monstruos en un 10% por ronda, y reduce <color=#cc0e0e>ataque normal</color> daño recibido por ronda en un 10%.",
  str_world_boss_bossdesc_7101007 = "Daño del contador de elementos aurorianos +100 %.\nLos mosaicos en los que los aurorianos generan objetos invocables se convierten en mosaicos cromáticos.",
  str_world_boss_leveldesc_normal_7101007 = "- Cuando aparece una nueva convocatoria de Aurorian en el campo, la ficha debajo se convierte en una ficha cromática.",
  str_world_boss_leveldesc_hard_7101007 = "- Cuando aparece una nueva convocatoria de Aurorian en el campo, la ficha debajo se convierte en una ficha cromática.\n- El <color=#cc0e0e>daño de la habilidad activa</color> de Aurorian aumenta en un 100%.\n- Cuando el <color=#cc0e0e>HP actual</color> del clon de Augean es superior al 90%, se beneficia de un aumento del 100% en DEF.",
  str_world_boss_bossdesc_7101003 = "Daño del contador de elementos aurorianos +100 %.\nCuando hay unidades convocadas por Aurorianos en el campo de batalla, el ATK aumenta en un 10%.",
  str_world_boss_leveldesc_normal_7101003 = "- Cuando hay unidades invocadas por Aurorianos en el campo de batalla, el ATK del invocador aumenta en un 10%.",
  str_world_boss_leveldesc_hard_7101003 = "- Cuando hay unidades invocadas por Aurorianos en el campo de batalla, el ATK del invocador aumenta en un 10%.\n- Los monstruos son <color=#cc0e0e>inmunes al daño de Habilidades Activas</color>. El <color=#cc0e0e>daño de combo en cadena</color> recibido aumenta en un 30% y el <color=#cc0e0e>daño de ataque normal</color> recibido disminuye en un 30%.",
  str_world_boss_leveldesc_normal_7101009 = "- Cuando un Aurorian Francotirador usa un Combo en Cadena, lo usará 1 vez extra en el punto de inicio.",
  str_world_boss_leveldesc_hard_7101010 = "- Cuando un Aurorian Francotirador usa un Combo en Cadena, lo usará 1 vez extra en el punto de inicio.\n- Los Aurorians infligen un 50% de daño adicional a los <color=#cc0e0e>enemigos que han marcado</color>.\n- Minos' <color=#cc0e0e>la DEF se incrementa</color> en un 10%.",
  str_world_boss_bossdesc_7101009 = "Daño de contraataque de elemento auroriano +100 %\nCuando un Sniper Aurorian usa un Chain Combo, lo usará 1 vez más en el punto de inicio.",
  str_world_boss_leveldesc_normal_7101112 = "- Si la Habilidad Activa está lista, el ATK de los Aurorianos aumenta en un 15% en esta ronda.",
  str_world_boss_leveldesc_hard_7101112 = "- Si la Habilidad Activa está lista, el ATK de los Aurorianos aumenta en un 15% en esta ronda.\n- Aumenta el <color=#cc0e0e>número de Necrófagos Sombríos convocados a</color> 6.\n- Aumenta el <color=#cc0e0e>daño de la Habilidad Activa</color> de los Aurorianos en un 30% y restaura su HP en un 10% del daño de la Habilidad Activa.",
  str_world_boss_bossdesc_7101112 = "Daño del contador de elementos de los aurorianos +100 %.\nNozard es inmune al daño de ataque normal, y Gloom Ghouls es inmune al daño de habilidad.\nAumenta el ATK de los Aurorianos en esta ronda si su Habilidad Activa está lista.",
  str_world_boss_leveldesc_normal_7101013 = "- Cuando la habilidad activa está convirtiendo los colores de las casillas, inflige daño a los enemigos en función del número de casillas rojas generadas.",
  str_world_boss_leveldesc_hard_7101013 = "- Cuando la habilidad activa está cambiando los colores de las casillas, inflige daño a los enemigos basado en el número de casillas rojas generadas.\n- La <color=#cc0e0e>DEF de Casta aumenta</color> en un 20%\n- Cuando Casta está <color=#cc0e0e>en una casilla dañada</color>, su <color=#cc0e0e>DEF se reduce</color> en un 75%",
  str_world_boss_leveldesc_normal_7101011 = "- Cada 3 rondas, restablece los mosaicos dentro de 1 grupo circundante, genera algunos mosaicos azules en el borde del mapa.",
  str_world_boss_leveldesc_hard_7101011 = "- <color=#cc0e0e>Cada 2 rondas</color>, reinicia las casillas dentro de 1 cúmulo circundante, genera algunas casillas azules en el borde del mapa.\n- <color=#cc0e0e>Aumenta el daño del enemigo</color>, mientras que el <color=#cc0e0e>efecto de curación de los Aurorianos se incrementa</color> en un 80%\n. Cuando los Aurorianos <color=#cc0e0e>se curan a sí mismos</color>, <color=#cc0e0e>inflige daño verdadero a los enemigos</color> de acuerdo con la cantidad de curación.",
  str_world_boss_bossdesc_7101013 = "Daño Contra-atq. Elemental de Aurorians +100%.\nCuando la habilidad activa de un Aurorian genera casillas rojas, inflige daño a los enemigos.",
  str_world_boss_bossdesc_7101011 = "Daño Contra-atq. Elemental de Aurorians +100%.\nSolmorph reinicia las casillas circundantes y genera algunas casillas azules.",
  str_world_boss_bossdesc_7001098 = "Daño de Contraataque de Elemento Aurorian +100%\nGenera una Runa de Rayo cada ronda y convoca rayos después\nGenera Azulejos de Prisma Amarillo en forma de cruz después de que la runa desaparezca",
  str_world_boss_leveldesc_normal_70010981 = "- Genera una Runa de Relámpago debajo de los Aurorianos cada ronda y convoca rayos <color=#cc0e0e>después de que termina la conexión de las fichas</color>\n- <color=#cc0e0e>Genera Fichas de Prisma Amarillas en un patrón en forma de cruz</color> después de que la runa desaparece",
  str_world_boss_leveldesc_hard_70010982 = "- Genera una Runa de Rayo debajo de los Aurorianos cada ronda y convoca rayos <color=#cc0e0e>después de que termina la conexión de las fichas</color>\n- <color=#cc0e0e>Genera fichas de prisma amarillo en un patrón en forma de cruz</color> después de que la runa desaparece\n- El Jefe recibe <color=#cc0e0e>-50% de DMG de las habilidades activas</color>\n- Cada golpe de <color=#cc0e0e>Ataque Normal</color> aumentará el <color=#cc0e0e>daño del Combo en Cadena</color> del Auroriano en un 2% en esta ronda",
  str_world_boss_leveldesc_normal_7001102 = "- Cada vez que se lanza una <color=#cc0e0e>Habilidad Activa de conversión de casillas</color>, también convertirá una casilla alrededor del Jefe al elemento del capitán.",
  str_world_boss_leveldesc_hard_7001102 = "- Cada vez que se lanza una <color=#cc0e0e>Habilidad Activa de conversión de fichas</color>, también convertirá una ficha alrededor del Jefe en el elemento del capitán.\n- <color=#cc0e0e>Cada vez que se usa</color> una Habilidad Activa cada ronda, el Jefe recibe un 20% <color=#cc0e0e>menos de daño de las Habilidades Activas</color>, hasta 5 acumulaciones.\n- Cada golpe de <color=#cc0e0e>Ataque Normal</color> aumentará el <color=#cc0e0e>daño del Combo en Cadena del Auroriano</color> en un 4% en esta ronda.",
  str_world_boss_bossdesc_7001102 = "Aumenta el Daño de Contraataque de Elemento Aurorian en un 100%.\nAl usar una Habilidad Activa de conversión de fichas, también convierte las fichas alrededor del jefe.",
  str_world_boss_leveldesc_normal_7001104 = "- Cuando el <color=#cc0e0e>HP del equipo es superior al 60%</color>, aumenta el ATK de todos los Aurorianos aliados en un 15%.\n- Al entrar al campo de batalla, los Arorianos recibirán daño equivalente al 50% de su HP máximo.",
  str_world_boss_leveldesc_hard_7001104 = "- Cuando los <color=#cc0e0e>HP del equipo son superiores al 75%</color>, <color=#cc0e0e>aumenta el ATK de todos los Aurorianos aliados en un 25%</color>.\n- Cuando los <color=#cc0e0e>HP del equipo caen por debajo del 40%</color>, <color=#cc0e0e>el ATK de todos los Aurorianos aliados disminuye en un 25%</color>.\n- Al entrar en el campo de batalla, nuestros aliados recibirán daño igual al 50% de su HP máximo.\n- <color=#cc0e0e>Cada curación</color> en la ronda actual obtiene un aumento del 10%, hasta 20 acumulaciones.",
  str_world_boss_bossdesc_7001104 = "Aumenta el daño del contador del elemento auroriano en un 100%. El HP auroriano influye en el daño infligido. Al entrar al campo de batalla, los Aurorianos recibirán un daño equivalente al 50% de su HP máximo.",
  str_world_boss_leveldesc_normal_7001105 = "- Kanna aparece en el campo de batalla para animar a sus amigos, mientras convierte las 4 casillas que la rodean en <color=#cc0e0e>casillas rojas dañadas</color>.\n- Cuando los Aurorians pasan por las 4 casillas que rodean a Kanna, <color=#cc0e0e>el conteo de combo aumenta en 10</color> por cada casilla por la que pasan.",
  str_world_boss_leveldesc_hard_7001105 = "- Kanna aparece en el campo de batalla para animar a sus amigos, mientras convierte las 4 fichas que la rodean en <color=#cc0e0e>fichas rojas dañadas</color>.\n- Cuando los Aurorians pasan por las 4 fichas que rodean a Kanna, el <color=#cc0e0e>conteo de combos aumenta en 10</color> por cada ficha por la que pasan.\n- En la cuarta ronda, los tiempos de enfriamiento de todas las habilidades de Aurorian se reducen en 1.\n- El Emperador de la Muerte posee la habilidad extremadamente amenazante <color=#cc0e0e>Fin del Destino</color>.",
  str_world_boss_bossdesc_7001105 = "Daño de Contraataque de Elemento Aurorian +100%\nKanna aparece en el campo de batalla para animar a sus amigos con aliento.",
  str_world_boss_leveldesc_normal_7001106 = "- Tohru aparece en el campo de batalla para animar a sus amigos, lanzando habilidades en cada ronda e infligiendo daño 5 veces. Esta habilidad también reiniciará las fichas no amarillas dentro de 1 grupo circundante.",
  str_world_boss_leveldesc_hard_7001106 = "- Tohru aparece en el campo de batalla para animar a sus amigos, lanzando habilidades en cada ronda para infligir daño 5 veces en total, y reiniciando las fichas no amarillas dentro de 1 grupo circundante.\n- En la cuarta ronda, los tiempos de enfriamiento de todas las habilidades de Aurorian se reducen en 1.\n- Schummer posee la habilidad de <color=#cc0e0e>mejorar significativamente sus atributos</color>.",
  str_world_boss_bossdesc_7001106 = "Daño de Contraataque de Elemento Aurorian +100%\nTohru aparece en el campo de batalla para animar a sus amigos con aliento.",
  str_world_boss_bossdesc_7001110 = "Daño del contador de elementos aurorianos +100%.\nLos ataques normales de los aurorianos reducen las acumulaciones de veneno en sí mismos.",
  str_world_boss_leveldesc_normal_7001110 = "- <color=#cc0e0e>Usar Habilidades Activas</color> <color=#cc0e0e>genera 2 Azulejos Oscuros</color> dentro de 1 grupo circundante del jefe.\n- Los ataques normales de los Aurorianos reducen las pilas de veneno en sí mismos.",
  str_world_boss_leveldesc_hard_7001110 = "- <color=#cc0e0e>Usar Habilidades Activas</color> <color=#cc0e0e>genera 1 Ficha Oscura</color> dentro de 1 cúmulo circundante del jefe.\n- Los ataques normales de los Aurorianos reducen las acumulaciones de veneno en sí mismos.\n- <color=#cc0e0e>Reduce el daño recibido</color> en las 8 fichas exteriores del Jefe.\n- <color=#cc0e0e>Pasar por una Ficha Oscura</color> <color=#cc0e0e>aumenta el ATQ</color> de todos los Aurorianos en el equipo.",
  str_world_boss_leveldesc_normal_7001111 = "- El Aurorian en la posición de capitán inflige 1 instancia extra de daño con cada Ataque Normal.",
  str_world_boss_leveldesc_hard_7001111 = "- El Auroriano en la posición de capitán inflige 1 instancia adicional de daño con cada Ataque Normal.\n- Reduce el daño que los enemigos reciben de las Habilidades Activas en un 80%.\n- Aumenta el daño que los enemigos reciben de los Ataques Normales en un <color=#cc0e0e>30%</color>.",
  str_world_boss_bossdesc_7001111 = "Daño de Contraataque de Elemento Aurorian +100%\nEl Aurorian en la posición de capitán inflige daño adicional con cada Ataque Normal.",
  str_world_boss_leveldesc_normal_7001112 = "- Por cada mosaico <color=#cc0e0e>rojo</color> en el campo, el daño final del auroriano aumenta en <color=#cc0e0e>1%</color>.",
  str_world_boss_leveldesc_hard_7001112 = "- Por cada ficha <color=#cc0e0e>roja</color> en el campo, el daño final del Auroriano aumenta en un <color=#cc0e0e>1%</color>.\n- Aparecerán 2 Buscadores en el campo, a quienes el Auroriano no puede infligir daño.\n- Los Buscadores poseen una <color=#cc0e0e>habilidad de contraataque</color> y se moverán después de que el Auroriano libere una Habilidad Activa.",
  str_world_boss_bossdesc_7001112 = "Daño del contador de elementos aurorianos +100%.\nLas fichas rojas en el campo aumentan el daño para los aurorianos.",
  str_world_boss_leveldesc_normal_7001113 = "- Una vez derrotado un enemigo, transforma la posición propia en una <color=#cc0e0e>ficha cromática</color>.",
  str_world_boss_leveldesc_hard_7001113 = "- Una vez derrotado un enemigo, transforma la posición propia en una <color=#cc0e0e>ficha cromática</color>.\n- Con cada Ataque Normal, el Auroriano acumula pilas, con cada pila aumentando el daño de la habilidad de Combo en Cadena en <color=#cc0e0e>3%</color>.\n- Reduce el daño que los enemigos reciben de las Habilidades Activas en un <color=#cc0e0e>80%</color>.",
  str_world_boss_bossdesc_7001113 = "Daño de Contraataque de Elemento Aurorian +100%\nGenera mosaicos cromáticos al derrotar a un enemigo planta.",
  str_world_boss_leveldesc_normal_7001114 = "- Las habilidades de daño de área de los aurorianos pueden limpiar los mosaicos de marca de veneno.",
  str_world_boss_leveldesc_hard_7001114 = "- Las habilidades de daño de área de los aurorianos pueden usarse para eliminar mosaicos de Marca de Veneno.\n- Al comienzo de la batalla y al usar Embestida de Mariposa, el jefe invoca muchos mosaicos de Marca de Veneno.\n- Cada ronda, 1 <color=#cc0e0e>Mosaico Oscuro</color> aparecerá alrededor de los aurorianos.",
  str_world_boss_bossdesc_7001114 = "Daño del contador de elementos aurorianos +100%\nConvierte las fichas de Marca de Veneno en Fichas Oscuras al limpiarlas",
  str_world_boss_leveldesc_normal_7001115 = "- Cuando un pantano desaparece, la casilla que ocupa se convertirá en el mismo color que el Capitán.",
  str_world_boss_leveldesc_hard_7001115 = "- Cuando un cenagal desaparece, la ficha que ocupa se convertirá en el mismo color que el Capitán.\n- Cuando un cenagal desaparece, la ficha que ocupa se cambiará automáticamente a una <color=#cc0e0e>Ficha Oscura</color>.\n- Aumenta el daño de la habilidad de Combo en Cadena del Auroriano, que actualmente es el Capitán, en un <color=#cc0e0e>50%</color>.\n- El jefe es <color=#cc0e0e>inmune al ataque normal de los Aurorianos</color>.",
  str_world_boss_bossdesc_7001115 = "Daño de Contraataque de Elemento Aurorian +100%\nCuando un cenagal desaparece, la casilla que ocupaba se convertirá en el mismo color que el Capitán.",
  str_world_boss_bossdesc_7001119 = "Daño de Contraataque de Elemento Aurorian +100%\nGenera una Ficha Oscura en la ubicación de un fantasma cuando muere\n5 columnas de fichas centradas en el jefe se mueven hacia atrás 1 ficha cada ronda",
  str_world_boss_leveldesc_normal_7001119 = "- Los fantasmas generan una Casilla Oscura en su ubicación cuando mueren.\n- 5 columnas de casillas centradas en el jefe retroceden 1 casilla cada ronda.",
  str_world_boss_leveldesc_hard_7001119 = "- Los fantasmas generan Casillas Oscuras en su ubicación cuando mueren durante las rondas de Aurorian.\n- 5 columnas de casillas centradas en el jefe se mueven hacia atrás 1 casilla cada ronda.\n- Pasar por una Casilla Oscura aumenta el daño de la Habilidad Activa. Cada uso de una Habilidad Activa consume cargas.",
  str_world_boss_eliminate_mode = "Modo de Iluminación",
  str_world_boss_eliminate = "Códice Desolación de Iluminación",
  str_world_boss_eliminate_tip1 = "Modo de Iluminación del Códice Desolación",
  str_world_boss_eliminate_tip2 = "¡El modo Iluminación para el Códice Desolación ha vuelto!\nEn el modo Iluminación, no es necesario conectar las fichas; simplemente toca las fichas para eliminarlas.\nDespués de eso, los Aurorianos pueden lanzar Combos en Cadena basados en el número de fichas eliminadas.",
  str_world_boss_bossdesc_7001121 = "Daño del contador de elementos aurorianos +100 %.\nElimina el Cañón de Salva y se generará una Ficha Oscura en el lugar a voluntad.\nAumenta permanentemente el Daño de Ataque Normal después de pasar por una Ficha Oscura.",
  str_world_boss_bossdesc_7001123 = "El juego termina cuando la bestia Nian destruye la puerta y entra en la ciudad.\nDaño de Contraataque de Elemento Aurorian +100%.\nEntra en la Hora de Aurora cada dos rondas.\nLanza una Habilidad Activa para asustar y hacer retroceder a la bestia Nian.",
  str_world_boss_bossdesc_7001125 = "El Daño de Contraataque de Elemento de los Aurorianos +100%.\nDespués de la teleportación, el Auroriano convierte las fichas debilitadas cercanas en fichas mejoradas.",
  str_world_boss_bossdesc_7001126 = "Daño de Contraataque de Elemento Aurorian +100%\nSe cuentan ganancias cuando los Aurorianos usan Habilidades Activas para infligir daño, teletransportarse o convertir fichas.\nCada 3 cuentas, el tiempo de enfriamiento de la Habilidad Activa Auroriana se reduce en 1 ronda.\nCada 3 cuentas, se inflige daño al jefe.",
  str_world_boss_bossdesc_7001127 = "El Daño del Contador de Elementos de los Aurorianos +100%.\nDespués de la teleportación, los aurorianos ganan un escudo basado en la distancia recorrida.",
  str_world_boss_bossdesc_7001128 = "El Daño del Contador de Elementos de los Aurorianos +100%.\nGenera una Ficha Oscura en la ubicación de un monstruo cuando es eliminado.",
  str_world_boss_bossdesc_7001129 = "Aumenta el daño del contador de elementos de los aurorianos en un 100%.\nLos jefes son inmunes a los ataques normales de los aurorianos.\nTodos los requisitos de Combo en Cadena de los aurorianos se reducen en 5 casillas.",
  str_world_boss_bossdesc_7001132 = "El Daño de Contraataque de Elemento de los Aurorianos +100%.\nGenera fichas mejoradas en las ubicaciones de aparición de los monstruos.\nLas fichas mejoradas ocupadas por monstruos se convertirán en fichas bloqueadas antes de las acciones de los monstruos.",
  str_world_boss_bossdesc_7001134 = "Aumenta el Daño de Contraataque de Elemento Aurorian en +100%.\nEl ATK de Aurorian aumenta permanentemente al pasar por Mosaicos Oscuros.\nEl jefe convoca a Eclipsites más pequeños adicionales cuando está enfurecido.\nLos Eclipsites más pequeños transfieren cualquier daño recibido al jefe.\nLos Eclipsites más pequeños dejan Mosaicos Oscuros al morir.",
  str_world_boss_bossdesc_7001136 = "Daño de Contraataque de Elemento Aurorian +100%\nEl daño del debilitamiento del enemigo se incrementa significativamente.\nLas unidades de Illumina son inmunes al daño de ataque directo.\nEl daño recibido por las unidades de Illumina se transfiere al líder.",
  str_world_boss_bossdesc_7001137 = "Daño de Contraataque de Elemento Aurorian +100%.\nLos ataques normales de los Aurorianos infligen 2 instancias de daño.\nEl jefe solo recibe un 10% de daño de las Habilidades Activas.",
  str_world_boss_multi_tips = "Durante el evento, las recompensas del Códice Desolación se triplican.",
  str_world_boss_bossdesc_7001142 = "Aumenta el daño del contador de elementos de los aurorianos en un 100%.\nEl daño aumenta a medida que la cordura se acerca a 50.\nRestaura la cordura al pasar por mosaicos oscuros.\nReduce significativamente la cordura cuando la escena colapsa.",
  str_world_boss_bossdesc_7001143 = "Aumenta el daño del contador de elementos de los aurorianos en un 100%.\nAumenta significativamente el daño ignorando la defensa de los aurorianos.\nGenera mosaicos oscuros donde se derrotan a los monstruos.",
  str_world_boss_bossdesc_7001145 = "Aumenta el Daño de Contraataque de Elemento Aurorian en un 100%.\nEl daño recibido por los faros se transfiere al jefe.\nLos faros reciben más daño de los Combos en Cadena, pero menos daño de los Ataques Normales.\nLos Aurorians generan mosaicos oscuros cromáticos a su alrededor.",
  str_world_boss_bossdesc_7001146 = "Aumenta el Daño del Contador de Elementos de Aurorian en un 100%.\nGenera un gran número de Mosaicos Oscuros alrededor del jefe.",
  str_world_boss_bossdesc_7002019 = "Aumenta el Daño del Contador de Elementos de Aurorian en un 100%.\nAcelera el tiempo de enfriamiento restante de la habilidad de Aurorian en rondas específicas.\nEl lanzamiento continuo de Habilidades Activas aumenta temporalmente el ATK del equipo.",
  str_world_boss_bossdesc_7001148 = "Daño del contador de elementos aurorianos +100 %.\nGenera una ficha mejorada después de aplastar un guijarro.",
  str_world_boss_bossdesc_7001149 = "Daño del contador de elementos aurorianos +100%\nGenera mosaicos oscuros azules cuando se derrota a un enemigo."
}
